const pageTitle = 'Exam Tips';
__eta.res+='\n\n<div class="page-header">\n  <h1 class="page-title"><span style="color:var(--htb-green)">></span> CPTS Exam Tips</h1>\n  <p class="page-subtitle">25 battle-tested strategies from CPTS passers. Read these before exam day.</p>\n</div>\n\n<style>\n.tips-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 1rem; margin-top: 1.5rem; }\n.tip-card { background: var(--htb-surface); border: 1px solid var(--htb-border); border-radius: 10px; padding: 1.25rem; position: relative; transition: border-color 0.2s, transform 0.2s; }\n.tip-card:hover { border-color: var(--htb-green); transform: translateY(-2px); }\n.tip-card.critical { border-left: 3px solid var(--htb-red); }\n.tip-card.important { border-left: 3px solid var(--htb-orange, #f59e0b); }\n.tip-card.good { border-left: 3px solid var(--htb-green); }\n.tip-number { font-size: 0.7rem; font-family: var(--font-mono); color: var(--text-muted); background: var(--htb-bg); padding: 2px 8px; border-radius: 4px; display: inline-block; margin-bottom: 0.5rem; }\n.tip-category { font-size: 0.65rem; font-family: var(--font-mono); color: var(--htb-green); text-transform: uppercase; letter-spacing: 1px; float: right; margin-top: 2px; }\n.tip-title { font-size: 0.95rem; font-weight: 600; color: var(--text-primary); margin: 0.4rem 0 0.6rem; }\n.tip-body { font-size: 0.83rem; color: var(--text-secondary); line-height: 1.6; }\n.tip-body code { background: var(--htb-bg); padding: 1px 5px; border-radius: 3px; font-family: var(--font-mono); font-size: 0.8rem; color: var(--htb-green); }\n.section-title { font-size: 1.1rem; font-family: var(--font-mono); color: var(--htb-green); margin: 2rem 0 0.75rem; padding-left: 0.5rem; border-left: 3px solid var(--htb-green); }\n.legend { display: flex; gap: 1.5rem; margin-top: 1rem; font-size: 0.75rem; color: var(--text-muted); font-family: var(--font-mono); }\n.legend-item { display: flex; align-items: center; gap: 0.4rem; }\n.legend-dot { width: 10px; height: 10px; border-radius: 2px; }\n</style>\n\n<div class="legend">\n  <span class="legend-item"><span class="legend-dot" style="background:var(--htb-red)"></span> Critical — exam-defining</span>\n  <span class="legend-item"><span class="legend-dot" style="background:#f59e0b"></span> Important — do this every time</span>\n  <span class="legend-item"><span class="legend-dot" style="background:var(--htb-green)"></span> Good practice — separates passers</span>\n</div>\n\n<h2 class="section-title">// Pre-Exam Preparation</h2>\n<div class="tips-grid">\n\n  <div class="tip-card critical">\n    <span class="tip-number">#01</span><span class="tip-category">Preparation</span>\n    <div class="tip-title">Set Up Your Report Template BEFORE Exam Day</div>\n    <div class="tip-body">Install and configure SysReptor (or your preferred tool) the week before. Have a blank report with all sections pre-created: Executive Summary, Scope, Methodology, Finding Summary Table, and at least 10 empty finding slots. On exam day, you open it and start filling in data — not configuring tools.</div>\n  </div>\n\n  <div class="tip-card critical">\n    <span class="tip-number">#02</span><span class="tip-category">Preparation</span>\n    <div class="tip-title">Build a Note-Taking Template with Sections for Every Host</div>\n    <div class="tip-body">Use CherryTree or Obsidian with a template: Host IP, Open Ports, Services, Credentials Found, Vulnerabilities, Flags, and Draft Finding. Create the node before you enumerate — paste data in as you discover it. Searching your notes at hour 60 of the exam is 10x faster than scanning grep history.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#03</span><span class="tip-category">Preparation</span>\n    <div class="tip-title">Test Your VPN and Lab Access 12 Hours Before Start</div>\n    <div class="tip-body">Connect to the HTB VPN, verify <code>tun0</code> is up, ping the lab gateway. Exam day VPN issues happen. Knowing your setup works means any exam-day problem is environment, not configuration. Have the HTB support contact ready.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#04</span><span class="tip-category">Preparation</span>\n    <div class="tip-title">Pre-Stage Your Tools — Don\'t Install During the Exam</div>\n    <div class="tip-body">Verify these work before exam day: <code>nmap</code>, <code>ffuf</code>, <code>bloodhound-python</code>, <code>impacket</code> (all tools), <code>evil-winrm</code>, <code>chisel</code>, <code>ligolo-ng</code>, <code>certipy</code>, <code>nxc</code> (NetExec), <code>mimikatz</code>, <code>rubeus</code>, <code>hashcat</code>. Install Sliver or Metasploit for C2. Downloading tools during the exam wastes precious time.</div>\n  </div>\n\n  <div class="tip-card good">\n    <span class="tip-number">#05</span><span class="tip-category">Preparation</span>\n    <div class="tip-title">Practice Writing One Full Finding Before the Exam</div>\n    <div class="tip-body">Take any HTB machine you\'ve rooted and write a professional finding for the initial foothold. Title, CVSS, affected host, PoC steps, business impact, remediation. Time yourself. If it takes more than 20 minutes, practice more. The exam requires 5-10 findings in the report.</div>\n  </div>\n\n</div>\n\n<h2 class="section-title">// During the Exam — Methodology</h2>\n<div class="tips-grid">\n\n  <div class="tip-card critical">\n    <span class="tip-number">#06</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Read the Scope Document First — Completely</div>\n    <div class="tip-body">Before scanning a single host, read the entire exam brief. Know exactly which IPs are in scope, which are out of scope, what credentials you\'ve been given, and the network topology. CPTS is grey-box — you will receive starting credentials. Missing this costs hours.</div>\n  </div>\n\n  <div class="tip-card critical">\n    <span class="tip-number">#07</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Screenshot Everything — As You Go, Not Retrospectively</div>\n    <div class="tip-body">Every pivotal action needs a screenshot: initial shell gained (showing hostname + whoami/id), every privilege escalation proof, every lateral move, every credential found, every flag. The report reviewer must reproduce your work. Lab access expires — you cannot go back.</div>\n  </div>\n\n  <div class="tip-card critical">\n    <span class="tip-number">#08</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Allocate Days 9-10 Purely for Report Writing</div>\n    <div class="tip-body">The exam is 10 days. Stop exploiting by end of day 8 and spend two full days on the report. A well-written report beats a sloppy one with more flags. The report IS the submission — reviewers cannot credit what they cannot verify.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#09</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Write Draft Findings AS You Discover Vulnerabilities</div>\n    <div class="tip-body">When you exploit something, open SysReptor/your report and write a draft finding immediately — even 3 sentences. Title, what you ran, what you got. You will have 100x better recall writing it at hour 10 than at hour 200 when you\'re exhausted and trying to reconstruct the attack chain.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#10</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Use the Two-Pass Nmap Method on Every Target</div>\n    <div class="tip-body">Pass 1: <code>nmap -p- --min-rate 10000 -oA host/full IP</code>. Pass 2: <code>nmap -sV -sC -O -p [ports] -oA host/targeted IP</code>. Never skip -p-. Missing a service on a non-standard port because you only scanned top-1000 is the most common preventable CPTS failure.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#11</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Spray Every Credential Against Every Service</div>\n    <div class="tip-body">Every password you find gets sprayed immediately against: SMB, SSH, WinRM, RDP, FTP, web apps, MSSQL, MySQL, and any other open service. Use <code>nxc smb 10.10.10.0/24 -u user -p pass</code> for network-wide spray. Credential reuse is extremely common — it\'s an intended exam mechanic.</div>\n  </div>\n\n  <div class="tip-card good">\n    <span class="tip-number">#12</span><span class="tip-category">Methodology</span>\n    <div class="tip-title">Keep a Running Credential Log</div>\n    <div class="tip-body">Maintain a table in your notes: Username | Password/Hash | Source | Services Tested | Works On. Every credential from every source goes here. At exam hour 50, when you\'re stuck, this table often contains your next move that you forgot about from hour 15.</div>\n  </div>\n\n</div>\n\n<h2 class="section-title">// Technical Tactics</h2>\n<div class="tips-grid">\n\n  <div class="tip-card critical">\n    <span class="tip-number">#13</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Add Every Discovered Hostname to /etc/hosts Immediately</div>\n    <div class="tip-body">Many CPTS targets serve completely different content based on the Host header (virtual host routing). <code>echo \'10.10.10.5 target.htb admin.target.htb\' >> /etc/hosts</code>. Always attempt VHost fuzzing too — many machines have a hidden admin or dev VHost as the intended entry point.</div>\n  </div>\n\n  <div class="tip-card critical">\n    <span class="tip-number">#14</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Run BloodHound Collection Immediately After AD Access</div>\n    <div class="tip-body"><code>bloodhound-python -u user -p pass -d domain.local -c all -ns DC_IP</code>. Do this as soon as you have any domain credential — even low-privilege. BloodHound shortest path analysis from your compromised user to Domain Admins reveals the entire attack chain. Look for: Kerberoastable accounts, AS-REP Roastable accounts, AdminTo edges, DCSync rights.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#15</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Check sudo -l Before Any Complex Privilege Escalation</div>\n    <div class="tip-body"><code>sudo -l</code> takes 1 second and is the fastest Linux privesc check. If any binary is listed with NOPASSWD, check GTFOBins immediately. Vim, find, python, awk, bash, tar, nmap — all have GTFOBins shell escape techniques. This resolves 30% of Linux privesc in under 60 seconds.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#16</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Check SeImpersonatePrivilege on Every Windows Shell</div>\n    <div class="tip-body">Run <code>whoami /priv</code> immediately on every Windows shell. SeImpersonatePrivilege (common for service accounts, IIS, MSSQL) → PrintSpoofer or GodPotato for instant SYSTEM. <code>.\\PrintSpoofer.exe -i -c cmd</code>. This privilege is present on 60%+ of CPTS Windows boxes.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#17</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Upgrade Every Linux Shell to a Full PTY Immediately</div>\n    <div class="tip-body">Without PTY upgrade: tab completion fails, Ctrl+C kills your shell, su fails, text editors crash. Upgrade: (1) <code>python3 -c \'import pty;pty.spawn("/bin/bash")\'</code>, (2) Ctrl+Z, (3) <code>stty raw -echo; fg</code>, (4) <code>export TERM=xterm</code>. Alternatively: <code>script /dev/null -c bash</code>.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#18</span><span class="tip-category">Technical</span>\n    <div class="tip-title">When Stuck on Web Apps — Check Source Code and JS Files</div>\n    <div class="tip-body">Right-click > View Page Source. Look for: API endpoints in JavaScript, hidden form fields, commented-out paths, admin routes. Use DevTools Network tab to capture all XHR/fetch requests. Run <code>curl app.js | grep -E \'api|endpoint|key|token|admin\'</code>. API endpoints often have missing auth on non-obvious methods.</div>\n  </div>\n\n  <div class="tip-card good">\n    <span class="tip-number">#19</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Use Ligolo-ng for Pivoting — It\'s Faster Than Chisel</div>\n    <div class="tip-body">Ligolo-ng creates a full TUN interface — no proxychains needed. All tools work natively. Setup: <code>./proxy -selfcert</code> on attacker, <code>./agent -connect ATTACKER:11601 -ignore-cert</code> on target. Then in ligolo console: <code>session</code>, <code>start</code>, add route <code>ip route add 172.16.0.0/24 dev ligolo</code>. Now scan the internal subnet directly.</div>\n  </div>\n\n  <div class="tip-card good">\n    <span class="tip-number">#20</span><span class="tip-category">Technical</span>\n    <div class="tip-title">Run winPEAS and linPEAS — But Read the Output Carefully</div>\n    <div class="tip-body">These tools generate hundreds of lines. Focus on: RED items (critical findings), credential sections (grep for \'password\' in output), service misconfigurations, scheduled tasks, and registry entries. Pipe to file: <code>.\\winPEAS.exe > peas.txt</code>, then grep. Don\'t blindly execute every suggestion.</div>\n  </div>\n\n</div>\n\n<h2 class="section-title">// Report Writing</h2>\n<div class="tips-grid">\n\n  <div class="tip-card critical">\n    <span class="tip-number">#21</span><span class="tip-category">Reporting</span>\n    <div class="tip-title">Every Finding Needs: Title, CVSS, PoC, Impact, Remediation</div>\n    <div class="tip-body">Minimum viable finding: Specific title (not "web issue" — "Stored XSS in Comment Field Allows Session Hijacking"), CVSS 3.1 score with vector, affected host(s), numbered PoC steps with screenshots, business impact in non-technical language, specific remediation steps. Missing any of these gets findings downgraded or rejected.</div>\n  </div>\n\n  <div class="tip-card critical">\n    <span class="tip-number">#22</span><span class="tip-category">Reporting</span>\n    <div class="tip-title">Executive Summary Must Have ZERO Technical Jargon</div>\n    <div class="tip-body">Write for a non-technical C-level reader who has never heard of "Kerberoasting" or "SQLi". Use: "An attacker without a valid account could access the payroll database" — not "Unauthenticated SQL injection on the login endpoint". One paragraph, overall risk rating, top 3 business impacts, recommended priority action.</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#23</span><span class="tip-category">Reporting</span>\n    <div class="tip-title">Include a Finding Summary Table with Color-Coded Severity</div>\n    <div class="tip-body">A table listing all findings by title, severity, affected host, and remediation status. This lets busy executives scan the entire report in 60 seconds. SysReptor generates this automatically. If writing manually, use: Critical (red), High (orange), Medium (yellow), Low (blue), Info (gray).</div>\n  </div>\n\n  <div class="tip-card important">\n    <span class="tip-number">#24</span><span class="tip-category">Reporting</span>\n    <div class="tip-title">Proofread Twice — Typos Undermine Credibility</div>\n    <div class="tip-body">A report with spelling errors signals carelessness to reviewers. Run spellcheck in your word processor. Read each finding aloud to catch awkward phrasing. Have someone else read the executive summary. Proofread AFTER a full night\'s sleep — your tired eyes miss errors your rested eyes catch.</div>\n  </div>\n\n  <div class="tip-card good">\n    <span class="tip-number">#25</span><span class="tip-category">Reporting</span>\n    <div class="tip-title">Test Your PDF Export Before Submission</div>\n    <div class="tip-body">Export your report to PDF and open it. Verify: all screenshots render (not broken images), code blocks don\'t overflow page margins, table formatting is intact, all sections are present, page numbers are correct, the cover page has the correct date and assessment type. PDF rendering bugs discovered at submission time are catastrophic.</div>\n  </div>\n\n</div>\n\n<div style="margin-top:2rem; padding:1rem 1.5rem; background:var(--htb-surface); border:1px solid var(--htb-green); border-radius:8px; font-size:0.85rem; color:var(--text-secondary); font-family:var(--font-mono);">\n  <strong style="color:var(--htb-green)">// REMEMBER</strong> — The CPTS exam tests methodology, not just technical skill. A professional report with clear findings from 70% of machines beats an undocumented full compromise. Think like a pentester, write like a consultant.\n</div>\n';

